<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Application\Service\Visibility\TenantVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\TemplateSnippetRef;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\TemplateSnippetAttributes;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\TemplateSnippet;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetFilter;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetCursor;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetReadGateway;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetSlide;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateSnippetVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateSnippetReadGateway $readGateway,
        private readonly TemplateSnippetWriteGateway $writeGateway,
        private readonly TenantVisibilityService $tenantVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(TemplateSnippet $content): TemplateSnippetAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(TemplateSnippet $content): TemplateSnippetAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(TemplateSnippetAttributes $attributes, ?TemplateSnippet $original = null): TemplateSnippetAttributes
    {
        $this->logDebug("Copy with fixed for Template snippet");
        $span = $this->startSpan("Copy with fixed for  Template snippet");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new TemplateSnippetPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(TemplateSnippetAttributes $attributes, ?TemplateSnippet $original = null): TemplateSnippetAttributes
    {
        $this->logDebug("Copy with hidden for Template snippet");
        $span = $this->startSpan("Copy with hidden for  Template snippet");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|TemplateSnippetRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Template snippet");
        $span = $this->startSpan("Check visibility of an iterator for  Template snippet");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new TemplateSnippetRef($value));
            } elseif ($value instanceof TemplateSnippetRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new TemplateSnippetFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(TemplateSnippetFilter $filter, ?TemplateSnippetCursor $cursor = null): TemplateSnippetSlide
    {
        $this->logDebug("List visibles for Template snippet");
        $span = $this->startSpan("List visibles for  Template snippet");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (TemplateSnippet $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(TemplateSnippetFilter $filter): int
    {
        $this->logDebug("Count visibles for Template snippet");
        $span = $this->startSpan("Count visibles for  Template snippet");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(TemplateSnippetFilter $filter, ?TemplateSnippetCursor $cursor = null): TemplateSnippetSlide
    {
        $this->logDebug("List visibles for update for Template snippet");
        $span = $this->startSpan("List visibles for update for  Template snippet");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (TemplateSnippet $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(TemplateSnippetFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Template snippet");
        $span = $this->startSpan("Count visibles for update for  Template snippet");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(TemplateSnippetRef $ref): ?TemplateSnippet
    {
        $this->logDebug("Retrieve visible for Template snippet");
        $span = $this->startSpan("Retrieve visible for  Template snippet");
        try {
            $filter = new TemplateSnippetFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(TemplateSnippetRef $ref): ?TemplateSnippet
    {
        $this->logDebug("Retrieve visible for update for Template snippet");
        $span = $this->startSpan("Retrieve visible for update for  Template snippet");
        try {
            $filter = new TemplateSnippetFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?TemplateSnippetRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Template snippet");
        $span = $this->startSpan("Check fields for fix for Template snippet");
        try {
            $result = $this->dispatcher->dispatch(new TemplateSnippetCollectNonEditableFields(TemplateSnippet::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?TemplateSnippetRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Template snippet");
        $span = $this->startSpan("Check fields to hide for  Template snippet");
        try {
            $result = $this->dispatcher->dispatch(new TemplateSnippetCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(TemplateSnippetAttributes $attributes): TemplateSnippetAttributes
    {
        $this->logDebug("Check visibility of parent references for Template snippet");
        $span = $this->startSpan("Check visibility of parent references for  Template snippet");
        try {
            $tenant = $attributes->getTenant();
            if (null !== $tenant && !$this->tenantVisibilityService->checkVisibility($tenant)) {
                throw new NotFoundException("Unknown Tenant " . ($tenant->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(TemplateSnippetFilter $filter): TemplateSnippetFilter
    {
        $this->logDebug("Compose visibility filter for Template snippet");
        $span = $this->startSpan("Compose visibility filter for  Template snippet");
        try {
            $result = $this->dispatcher->dispatch(new TemplateSnippetRestrictFilterToVisibility($filter));
            return $result->templateSnippetFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(TemplateSnippet $value): bool
    {
        $this->logDebug("Check if item is visible for Template snippet");
        $span = $this->startSpan("Check if item is visible for  Template snippet");
        try {
            $result = $this->dispatcher->dispatch(new TemplateSnippetVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(TemplateSnippet $content, bool $inlist): TemplateSnippetAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Template snippet");
        $span = $this->startSpan("Prepare hydration to visible data for Template snippet");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new TemplateSnippetEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
